def _load_yaml(path: str | Path) -> dict:
    if yaml is None:
        return {}
    p = Path(path)
    if not p.exists():
        return {}
    try:
        with open(p, 'r') as f:
            return yaml.safe_load(f) or {}
    except Exception:
        return {}

